<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('siswa');$uid=(int)currentUser()['id_user'];$s=$koneksi->prepare("SELECT k.id_klaim,k.status_klaim,l.nama_barang,l.qr_token,lo.nama_lokasi,p.nama_penerima,p.tanggal_pengambilan FROM klaim k JOIN laporan l ON l.id_laporan=k.id_laporan JOIN lokasi lo ON lo.id_lokasi=l.id_lokasi LEFT JOIN pengambilan p ON p.id_klaim=k.id_klaim WHERE k.id_user=? AND k.status_klaim IN ('disetujui','diambil') ORDER BY k.created_at DESC");$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();$pageTitle='Bukti Klaim';require __DIR__.'/../includes/header.php';?><div class="panel"><h2>Bukti klaim barang</h2><p class="muted" style="font-size:12px">Tunjukkan informasi ini kepada petugas sekolah saat proses pengambilan.</p><?php if(!$rows->num_rows):?><div class="empty">Belum ada klaim yang disetujui.</div><?php endif;while($r=$rows->fetch_assoc()):?><div class="item"><div class="item-thumb">️</div><div class="item-info"><b><?=e($r['nama_barang'])?></b><small><?=e($r['nama_lokasi'])?> · <?=e($r['status_klaim'])?></small><small>Token verifikasi: <?=e(substr($r['qr_token'],0,14))?>••••••</small><?php if($r['nama_penerima']):?><small>Diterima oleh <?=e($r['nama_penerima'])?></small><?php endif;?></div><span class="badge <?=e($r['status_klaim'])?>"><?=e($r['status_klaim'])?></span></div><?php endwhile;?></div><?php require __DIR__.'/../includes/footer.php';?>
